'use strict';
(function(root){
const E=root.HZLCustomerEngine,configs=E.defaults(),cases={},chosen={Zinc:'baseline',Lead:'baseline',Silver:'baseline'},labels={Zinc:'Illustrative customer records',Lead:'Illustrative customer records',Silver:'Illustrative customer records'};
for(const m of Object.keys(configs))cases[m]=Object.fromEntries(['baseline','disruption','opportunity'].map(id=>[id,E.caseDefaults(m,id)]));
const revisions={Zinc:0,Lead:0,Silver:0};
let host=null,metal='Zinc',editing='disruption',page='customers',message='';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),n=(x,d=0)=>Number(x).toLocaleString('en-IN',{maximumFractionDigits:d});
const card=(t,sub,b)=>`<section class="card"><div class="card-head"><div><h2>${esc(t)}</h2><p>${esc(sub)}</p></div></div>${b}</section>`;
const table=(h,rows)=>`<div class="table-wrap"><table><thead><tr>${h.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const metric=(t,v,u)=>`<div class="kpi"><div class="kpi-label">${esc(t)}</div><div class="value">${n(v)} <span class="unit">${esc(u)}</span></div></div>`;
function changed(){revisions[metal]++;host.baselineChanged();}
function ctx(){return host.rawContext(metal);}
function outcomes(){const c=ctx();return ['baseline','disruption','opportunity'].map(id=>E.calculate(configs[metal],metal,c.months,cases[metal][id],c.pricing,c.cargo));}
function input(name,label,value,min,max,step='any'){return `<div class="field"><label for="cp-${name}">${esc(label)}</label><input id="cp-${name}" name="${name}" type="number" min="${min}" max="${max}" step="${step}" value="${value}" required></div>`;}
function monthly(r){return table(['Month','Expected '+r.unit,'Booked '+r.unit,'Domestic reserve','Residual export','Unserved'],r.rows.map(x=>[x.month,n(x.point),n(x.booked),n(x.domestic),n(x.export),n(x.unserved)]));}
function customerView(){const c=configs[metal],x=ctx(),b=E.calculate(c,metal,x.months,cases[metal].baseline,x.pricing,x.cargo),r=b.rows[0];return `<div class="kpis">${metric('Customer requirements',r.need,b.unit)}${metric('Baseline expected HZL',r.point,b.unit)}${metric('Booked orders',r.booked,b.unit)}${metric('Baseline conversion',r.point-r.booked,b.unit)}</div>${card('Customer planning inputs','Month-1 requirements are anchored to November 2026. Expected orders protect existing bookings.',`<form id="customer-inputs">${table(['Customer / sector','Grade','Need '+b.unit,'HZL share %','Booked '+b.unit,'Eligible'],c.accounts.map((a,i)=>[`<strong>${esc(a.name)}</strong><br>${esc(a.sector)}`,`<input aria-label="${esc(a.name)} grade" data-i="${i}" data-k="grade" value="${esc(a.grade)}" maxlength="100" required>`,...['need','share','booked'].map(k=>`<input aria-label="${esc(a.name)} ${k}" data-i="${i}" data-k="${k}" type="number" min="0" max="${k==='share'?100:1e9}" step="any" value="${a[k]}" required>`),`<input aria-label="${esc(a.name)} eligible" data-i="${i}" data-k="eligible" type="checkbox" ${a.eligible?'checked':''}>`]))}<div class="form-grid">${input('capacity','Monthly capacity ('+b.unit+')',c.capacity,1,1e9)}${input('buffer','Domestic buffer ('+b.unit+')',c.buffer,0,1e9)}${input('growth','Monthly requirement growth (%)',c.growth,-30,30)}</div><button type="submit">Update customer plan</button></form><p class="mini">Expected = max(booked, eligible requirement × achievable HZL share). Bookings are included, not added twice. Ineligible booked commitments remain visible as exceptions. Booked assumptions taper to 65% and 40% in the next two selected months; replace with approved monthly records for operations.</p>`)}${card('Three-month customer baseline','Reserve domestic orders / commitments plus buffer, capped at capacity.',monthly(b))}${card('Customer exceptions','Commitments and qualification need human review',table(['Customer','Exception'],r.accounts.filter(a=>a.eligibilityException||a.bookingException).map(a=>[esc(a.name),a.eligibilityException?'Booked commitment on an ineligible customer / grade':'Bookings exceed share-based opportunity']))+(!r.accounts.some(a=>a.eligibilityException||a.bookingException)?'<p>No eligibility or booking exceptions in this selected example.</p>':''))}<div class="actions"><button class="secondary" data-customer="template">Download customer-plan JSON</button><label for="customer-import">Import approved plan JSON, maximum 500 KB</label><input id="customer-import" type="file" accept=".json,application/json"></div>`;}
function chart(results){const max=Math.max(1,...results.flatMap(r=>r.rows.map(x=>x.point)))*1.15,colors=['#176c50','#b47a2c','#718ba5'];return `<svg class="chart" viewBox="0 0 900 320" role="img" aria-label="Baseline, disruption and opportunity expected orders by month in ${results[0].unit}">${[0,.5,1].map(v=>`<line x1="72" x2="872" y1="${250-200*v}" y2="${250-200*v}" stroke="#e1e9e4"/><text x="5" y="${254-200*v}">${n(max*v)}</text>`).join('')}${results[0].rows.map((x,i)=>`${results.map((r,j)=>`<rect x="${140+i*245+j*48}" y="${250-r.rows[i].point/max*200}" width="42" height="${r.rows[i].point/max*200}" fill="${colors[j]}"><title>${esc(r.scenario.title)} ${x.month}: ${n(r.rows[i].point)} ${r.unit}</title></rect>`).join('')}<text x="${205+i*245}" y="280" text-anchor="middle">${x.month}</text>`).join('')}</svg><div class="legend"><span>● Baseline</span><span>● Disruption</span><span>● Opportunity</span><span>${results[0].unit}; zero-based axis</span></div>`;}
function compareView(){const all=outcomes(),c=ctx(),s=cases[metal][editing],u=all[0].unit;return `<div class="scenario-cards">${all.map(r=>`<section class="card"><h2>${esc(r.scenario.title)}</h2><p>Three-month expected orders</p><div class="scenario-total">${n(r.total)} ${u}</div><p>First-month parity: ${n(r.parity,2)} INR/${u}</p><p>Domestic reserve: ${n(r.rows[0].domestic)} ${u}<br>Residual export: ${n(r.rows[0].export)} ${u}</p><button data-customer="use" data-case="${r.scenario.id}" ${chosen[metal]===r.scenario.id?'disabled':''}>${chosen[metal]===r.scenario.id?'Current commercial plan':'Use this case in dashboard'}</button></section>`).join('')}</div>${card('Monthly scenario comparison','Independent cases share the same customers and booking commitments.',chart(all)+table(['Month','Baseline '+u,'Disruption '+u,'Opportunity '+u],all[0].rows.map((r,i)=>[r.month,...all.map(a=>n(a.rows[i].point))])))}${card('Scenario assumptions','Editable conditional sensitivities, not probabilities or fitted geopolitical effects.',`<label for="customer-edit-case">Edit case</label><select id="customer-edit-case"><option value="disruption" ${editing==='disruption'?'selected':''}>Disruption</option><option value="opportunity" ${editing==='opportunity'?'selected':''}>Opportunity</option></select><form id="customer-scenario"><div class="form-grid">${[...new Set(configs[metal].accounts.map(a=>a.sector))].map((sector,i)=>input('sector'+i,sector+' change (%)',s.sectors[sector]||0,-50,50)).join('')}${s.profile.map((v,i)=>input('weight'+i,c.months[i]+' demand weight',v,0,1)).join('')}${input('referencePct','Reference price change (%)',s.referencePct,-50,100)}${input('premiumShift','Premium change (USD/'+u+')',s.premiumShift,-1000,1000)}${input('freightShift','Freight change (USD/'+u+')',s.freightShift,-1000,1000)}${input('fxPct','FX change (%)',s.fxPct,-50,100)}${input('dutyDelta','Hypothetical duty change (pp)',s.dutyDelta,-100,100)}${input('delay','Cargo delay (whole days)',s.delay,0,90,1)}<div class="field"><label for="customer-origin">Affected cargo origin</label><select id="customer-origin" name="origin">${['All',...new Set(c.cargo.map(a=>a.origin))].map(o=>`<option ${s.origin===o?'selected':''}>${esc(o)}</option>`).join('')}</select></div></div><label for="customer-rationale">Assumption rationale</label><textarea id="customer-rationale" name="rationale" maxlength="1000" required>${esc(s.rationale)}</textarea><button type="submit">Recalculate scenario</button></form><p class="mini">Demand weights taper by month; cost assumptions remain constant within each comparison case. Duty is a hypothetical percentage-point change, not a claimed legal rate or FTA entitlement. Case changes reset the commercial plan to baseline until a case is selected again.</p>`)}${card('Supply timing by scenario','Registered quantities remain accounted for, including arrivals outside the horizon.',table(['Month','Baseline arrivals '+u,'Disruption arrivals '+u,'Opportunity arrivals '+u],all[0].rows.map((r,i)=>[r.month,...all.map(a=>n(a.rows[i].arrivals))]))+table(['Case','Registered arrivals outside selected horizon '+u],all.map(a=>[a.scenario.title,n(a.arrivalsOutsideHorizon)])))}`;}
function explainView(){
 const all=outcomes(),r=all.find(a=>a.scenario.id===editing),b=all[0],u=r.unit;
 const contributions=r.rows[0].accounts.map(a=>[esc(a.name)+' / '+esc(a.sector),n(a.baseline),n(a.expected),n(a.delta),a.protectedBooking?'Booked commitment protected':!a.eligible?'Qualification blocks unbooked opportunity':`${n(r.scenario.sectors[a.sector]||0)}% sector sensitivity × ${r.scenario.profile[0]} weight`]);
 contributions.push(['Total',n(b.rows[0].point),n(r.rows[0].point),n(r.rows[0].delta),'Exact sum of customer contributions']);
 const bridge=table(['Input','Baseline','Conditional'],[['Metal reference USD/'+u,n(b.pricing.reference,2),n(r.pricing.reference,2)],['Premium USD/'+u,n(b.pricing.premium,2),n(r.pricing.premium,2)],['Freight USD/'+u,n(b.pricing.freight,2),n(r.pricing.freight,2)],['FX INR/USD',n(b.pricing.fx,2),n(r.pricing.fx,2)],['Duty assumption %',n(b.pricing.duty,2),n(r.pricing.duty,2)],['Import parity INR/'+u,n(b.parity,2),n(r.parity,2)]]);
 return `<label for="customer-explain-case">Explain case</label><select id="customer-explain-case"><option value="disruption" ${editing==='disruption'?'selected':''}>Disruption</option><option value="opportunity" ${editing==='opportunity'?'selected':''}>Opportunity</option></select>`
 +card('Why the first-month forecast changed',`${r.rows[0].month}; baseline ${n(b.rows[0].point)} ${u}, ${r.scenario.title.toLowerCase()} ${n(r.rows[0].point)} ${u}`,table(['Customer / sector','Baseline '+u,'Conditional '+u,'Contribution '+u,'Reason'],contributions))
 +card('Every month reconciles','Customer contributions sum to the displayed monthly change.',table(['Month','Baseline '+u,'Conditional '+u,'Net change '+u],r.rows.map(x=>[x.month,n(x.baselinePoint),n(x.point),n(x.delta)])))
 +card('Price and supply effects are separate','A cost change does not automatically become a demand coefficient.',bridge+`<p>${esc(r.scenario.rationale)}</p><p class="mini">This explains declared arithmetic, not observed causality or validated HZL outcomes. Supply disruptions need verified route exposure. Exports need grade, market access, credit and netback review.</p>`)+evidence();
}
function evidence(){const rows=root.HZLEventData.cases.filter(c=>c.metals.includes(metal)&&c.published<='2026-10-24');return card('Dated market evidence','Real published observations are separate from the scenario coefficients.',rows.map(c=>`<div class="planning-evidence"><strong>${esc(c.title)}</strong><p>${esc(c.fact)}</p><p class="mini">${esc(c.period)}; published ${c.published}. ${esc(c.limit)}</p><a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">${esc(c.source)} ↗</a></div>`).join(''));}
function render(which,h){const first=!host;host=h;page=which;if(first||metal!=='Silver')metal=h.selectedMetal;const c=ctx();let body;try{body=which==='customers'?customerView():which==='compare'?compareView():explainView();}catch(error){body=card('Scenario assumptions need review',error.message,'<p>Baseline commercial inputs changed. The comparison cannot use a negative premium, freight or invalid duty.</p><button data-customer="zero-cost">Reset comparison cost changes to zero</button>');}return `<div class="event-controls"><div><label for="customer-metal">Planning metal</label><select id="customer-metal">${Object.keys(configs).map(m=>`<option ${metal===m?'selected':''}>${m}</option>`).join('')}</select></div><div><label for="customer-horizon">Planning horizon</label><select id="customer-horizon"><option value="rolling" ${c.months[0]==='2026-11'?'selected':''}>Nov 2026 – Jan 2027</option><option value="quarter" ${c.months[0]==='2027-01'?'selected':''}>Q1 2027 · Jan – Mar</option></select></div><div><strong>${esc(labels[metal])}</strong><p class="mini">${c.months.join(' / ')}; ${configs[metal].unit}. Session only; refresh clears edits.</p></div></div><div class="context-line">Current customer case: ${cases[metal][chosen[metal]].title}. Comparison cases exclude separate event overlays. ${metal==='Silver'?'Silver uses kg in customer / scenario views. Main operating views cover Zinc and Lead; no trained Silver model.':'The selected case feeds the commercial dashboard.'} Default references use published Sep 2026 averages; edited reference prices and other commercial inputs are planning assumptions. Customers and cargo remain illustrative or unverified.</div><p id="customer-message" role="status">${esc(message)}</p>${body}<div class="actions"><button class="secondary" data-customer="export">Export customer and scenario decision pack</button></div>`;}
function save(name,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function refresh(){host.refresh();}
document.addEventListener('change',async e=>{if(e.target.id==='customer-horizon'){host.setHorizon(e.target.value);refresh();}if(e.target.id==='customer-metal'){metal=e.target.value;if(metal!=='Silver')host.selectMetal(metal);message='';refresh();}if(['customer-edit-case','customer-explain-case'].includes(e.target.id)){editing=e.target.value;refresh();}if(e.target.id==='customer-import'){try{const f=e.target.files[0];if(!f)return;if(f.size>500000)throw Error('Customer plan exceeds 500 KB');const c=E.validate(JSON.parse(await f.text()),metal);configs[metal]=c;cases[metal]=Object.fromEntries(['baseline','disruption','opportunity'].map(id=>[id,{...E.caseDefaults(metal,id),sectors:Object.fromEntries([...new Set(c.accounts.map(a=>a.sector))].map(s=>[s,0]))}]));chosen[metal]='baseline';labels[metal]='Imported customer plan — unverified';changed();message='Imported plan validated structurally; verify source and bookings before use.';refresh();}catch(err){document.getElementById('customer-message').textContent=err.message;}}});
document.addEventListener('submit',e=>{if(!['customer-inputs','customer-scenario'].includes(e.target.id))return;e.preventDefault();if(!e.target.reportValidity())return;try{const form=e.target,fd=new FormData(form);if(form.id==='customer-inputs'){const c=JSON.parse(JSON.stringify(configs[metal]));for(const el of form.querySelectorAll('[data-i]')){const a=c.accounts[Number(el.dataset.i)],k=el.dataset.k;a[k]=k==='eligible'?el.checked:k==='grade'?el.value:Number(el.value);}for(const k of ['capacity','buffer','growth'])c[k]=Number(fd.get(k));configs[metal]=E.validate(c,metal);chosen[metal]='baseline';changed();message='Customer baseline updated; review and reselect any scenario.';}else{const s=JSON.parse(JSON.stringify(cases[metal][editing]));[...new Set(configs[metal].accounts.map(a=>a.sector))].forEach((k,i)=>s.sectors[k]=Number(fd.get('sector'+i)));s.profile=[0,1,2].map(i=>Number(fd.get('weight'+i)));for(const k of ['referencePct','premiumShift','freightShift','fxPct','dutyDelta','delay'])s[k]=Number(fd.get(k));s.origin=String(fd.get('origin'));s.rationale=String(fd.get('rationale'));cases[metal][editing]=E.validateCase(s,configs[metal],ctx().pricing);chosen[metal]='baseline';changed();message='Scenario recalculated. Baseline remains the shared plan until you select a case.';}refresh();}catch(err){document.getElementById('customer-message').textContent=err.message;}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-customer]');if(!b)return;try{const a=b.dataset.customer;if(a==='zero-cost'){for(const id of ['disruption','opportunity'])for(const k of ['referencePct','premiumShift','freightShift','fxPct','dutyDelta'])cases[metal][id][k]=0;chosen[metal]='baseline';changed();message='Comparison costs reset explicitly to zero; review and edit the cases again.';refresh();}if(a==='use'){chosen[metal]=b.dataset.case;changed();message='Selected case now feeds customer-based orders and allocation. Previous event reviews require a new review.';refresh();}if(a==='template')save('HZL-'+metal+'-customer-plan.json',configs[metal]);if(a==='export')save('HZL-'+metal+'-customer-decision-pack.json',{classification:labels[metal],metal,config:configs[metal],selectedCase:chosen[metal],cases:cases[metal],outputs:outcomes(),sourceReference:ctx().source});}catch(err){document.getElementById('customer-message').textContent=err.message;}});
root.HZLCustomer={render,version:m=>revisions[m],baselineOnly(m){chosen[m]='baseline';revisions[m]++;},settings:m=>configs[m],accounts:m=>configs[m].accounts.map(a=>({...a,metal:m,demand:a.need,hzl:Math.round(a.need*a.share/100)})),baseline:(m,months)=>E.baseline(configs[m],m,months),current:(m,months,pricing,cargo)=>E.calculate(configs[m],m,months,cases[m][chosen[m]],pricing,cargo),label:m=>labels[m]+' · '+cases[m][chosen[m]].title,selected:m=>chosen[m],reset(){for(const m of Object.keys(configs)){configs[m]=E.defaults()[m];cases[m]=Object.fromEntries(['baseline','disruption','opportunity'].map(id=>[id,E.caseDefaults(m,id)]));labels[m]='Illustrative customer records';chosen[m]='baseline';revisions[m]++;}},snapshot:()=>({configs,cases,chosen,labels,revisions})};
})(window);
